/* NGAP (3GPP TS 38.413, Rel-16) - ASN.1 APER codec.
 *
 * The schema (src/schema.c) is generated by tools/gen_ngap_c.py from the pinned ASN.1 modules in docs/specs/asn1; a
 * generic APER codec (X.691, aligned variant) interprets it. PDUs are exchanged as JSON trees:
 *
 *   SEQUENCE           object of the present fields (OPTIONAL fields are simply absent). Extension additions the
 *                      schema does not know are kept under "_ext" as an array of hex open-type contents.
 *   CHOICE             object with one key, the alternative name. An unknown extension alternative is
 *                      {"_ext_choice": index, "raw": "<hex>"}.
 *   SEQUENCE OF        array.
 *   INTEGER            number. ENUMERATED: the name (a number for extension values the schema does not name).
 *   BOOLEAN            true/false. NULL: null (present as a key for OPTIONAL NULLs).
 *   OCTET STRING       lowercase hex string (use ngap_decode_as() for a CONTAINING type).
 *   BIT STRING         {"len": <bits>, "hex": "<hex>"} (unused trailing bits are zero).
 *   character strings  string.   OBJECT IDENTIFIER: hex of the content octets.
 *   protocol IE lists  array of {"id": n, "criticality": "reject|ignore|notify", "name": "<spec name>", "value": ...}.
 *                      An IE whose id the message does not define decodes to "value": {"_raw": "<hex>"} and is
 *                      re-encoded verbatim.
 *   PDU                {"initiatingMessage"|"successfulOutcome"|"unsuccessfulOutcome":
 *                        {"procedureCode": n, "criticality": "...", "value": <message>}}
 * Decoding is bounds-checked, depth-limited, and refuses to build more than NGAP_MAX_NODES values. */
#ifndef G5C_NGAP_H
#define G5C_NGAP_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include "g5c/base.h"
#include "g5c/json.h"
#include "g5c/ngap_ids.h"

#define NGAP_MAX_NODES 200000
#define NGAP_MAX_DEPTH 48

/* ---- schema (generated) ------------------------------------------------------------------------------------------ */

enum {
    NG_BOOL,
    NG_NULL,
    NG_INT,
    NG_ENUM,
    NG_SEQ,
    NG_SEQOF,
    NG_CHOICE,
    NG_OCTETS,
    NG_BITS,
    NG_STR,
    NG_OID,
    NG_ALIAS,
    NG_IE_CONTAINER,
    NG_IE_SINGLE,
    NG_EXT_CONTAINER,
    NG_PRIVATE_CONTAINER,
    NG_IE_LIST,
    NG_IE_PAIR_CONTAINER,
    NG_IE_PAIR_LIST,
    NG_PROCMSG
};

typedef struct ngap_type ngap_type;

typedef struct {
    const char *name;
    const ngap_type *type;
    uint8_t optional;
} ngap_field;

typedef struct {
    uint16_t id;
    uint8_t criticality; /* 0 reject, 1 ignore, 2 notify */
    uint8_t presence;    /* 0 optional, 1 conditional, 2 mandatory */
    const char *name;
    const ngap_type *type;
} ngap_ie_def;

typedef struct {
    const ngap_ie_def *defs;
    size_t n;
} ngap_ie_set;

struct ngap_type {
    uint8_t kind;
    const char *name;
    uint8_t has_lb, has_ub, ext;
    int64_t lb, ub;
    uint64_t span; /* ub - lb for INTEGER ranges (may exceed INT64_MAX) */
    const ngap_field *fields;
    size_t nfields, nroot;
    const char *const *names;
    size_t nnames;
    const ngap_type *elem, *alias, *contained;
    const ngap_ie_set *set;
    uint8_t strkind; /* NG_STR: 0 Printable, 1 Visible, 2 UTF8, 3 IA5; NG_PROCMSG: 0 init, 1 succ, 2 unsucc */
};

typedef struct {
    uint16_t code;
    uint8_t crit;
    const char *name;
    const ngap_type *init, *succ, *unsucc;
} ngap_proc;

typedef struct {
    const char *name;
    const ngap_type *type;
} ngap_named;

extern const ngap_type *const NGAP_PDU_TYPE;
extern const ngap_proc NGAP_PROCS[];
extern const size_t NGAP_NPROCS;
extern const ngap_named NGAP_NAMED[];
extern const size_t NGAP_NNAMED;

/* ---- codec -------------------------------------------------------------------------------------------------------- */

/* Decode an NGAP-PDU. Returns NULL and fills err on failure; caller frees the tree. */
g5c_json *ngap_decode(const uint8_t *buf, size_t len, char *err, size_t errcap);
/* Encode an NGAP-PDU tree, appending to out. 0 / -1 with err. */
int ngap_encode(const g5c_json *pdu, g5c_bytes *out, char *err, size_t errcap);
/* Same for a named ASN.1 type, e.g. "PDUSessionResourceSetupRequestTransfer" (the contents of OCTET STRING
 * (CONTAINING ...) IEs). NULL / -1 if the type name is unknown. */
g5c_json *ngap_decode_as(const char *type_name, const uint8_t *buf, size_t len, char *err, size_t errcap);
int ngap_encode_as(const char *type_name, const g5c_json *v, g5c_bytes *out, char *err, size_t errcap);

/* Convenience accessors on a decoded PDU. */
const char *ngap_pdu_kind(const g5c_json *pdu);              /* "initiatingMessage", ... or NULL */
const g5c_json *ngap_pdu_message(const g5c_json *pdu);       /* the message SEQUENCE ("value") or NULL */
const char *ngap_procedure_name(const g5c_json *pdu);        /* e.g. "id-InitialUEMessage" -> "InitialUEMessage" */
bool ngap_procedure_code(const g5c_json *pdu, int64_t *out);
/* Find an IE by id in a message's protocolIEs; returns its "value" or NULL. */
const g5c_json *ngap_find_ie(const g5c_json *message, int64_t id);

#endif
